(function(root){'use strict';const bank={"version":"form4-review-1.0.0","total":120,"topics":{"PROB":{"topicId":"T1","chapter":9,"name":"Probability of Combined Events"},"SET":{"topicId":"T2","chapter":4,"name":"Operations on Sets"},"LOGIC":{"topicId":"T3","chapter":3,"name":"Logical Reasoning"}},"questions":[{"id":"PROB-001","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1001,"difficulty":"Easy","curriculumStandards":["9.1.1"],"contextKind":"TEACHING_POOL","prompt":"A fair coin is tossed and a fair four-sided rune die numbered 1 to 4 is rolled independently. How many ordered outcomes (coin, number) are possible?","choices":[{"id":"PROB-001-choice-4a44dc15","label":"A","text":"10"},{"id":"PROB-001-choice-4b227777","label":"B","text":"4"},{"id":"PROB-001-choice-2c624232","label":"C","text":"8"},{"id":"PROB-001-choice-e7f6c011","label":"D","text":"6"}],"correctChoiceId":"PROB-001-choice-2c624232","hint":"Pair each coin result with every die result.","explanation":"There are 2 coin results and 4 die results, so 2 × 4 = 8 outcomes."},{"id":"PROB-002","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1002,"difficulty":"Easy","curriculumStandards":["9.1.1"],"contextKind":"TEACHING_POOL","prompt":"Two fair six-sided dice are rolled independently. Each outcome is an ordered pair (first die, second die). Which list contains every outcome with a total of 5?","choices":[{"id":"PROB-002-choice-f7448b32","label":"A","text":"{(1,4), (2,3)}"},{"id":"PROB-002-choice-904949b1","label":"B","text":"{(1,4), (2,3), (3,2), (4,1)}"},{"id":"PROB-002-choice-a20cb114","label":"C","text":"{(1,5), (2,4), (3,3), (4,2), (5,1)}"},{"id":"PROB-002-choice-1c4b79e2","label":"D","text":"{(5,5)}"}],"correctChoiceId":"PROB-002-choice-904949b1","hint":"List pairs in both orders when their entries differ.","explanation":"The four ordered pairs are (1,4), (2,3), (3,2) and (4,1). Each pair sums to 5."},{"id":"PROB-003","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1003,"difficulty":"Easy","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A fair coin is tossed and a fair four-sided rune die numbered 1 to 4 is rolled independently. Find P(Heads AND an even number).","choices":[{"id":"PROB-003-choice-f70b94ae","label":"A","text":"1/4"},{"id":"PROB-003-choice-d939926f","label":"B","text":"1/2"},{"id":"PROB-003-choice-52e90ae2","label":"C","text":"1/8"},{"id":"PROB-003-choice-5132a203","label":"D","text":"3/4"}],"correctChoiceId":"PROB-003-choice-f70b94ae","hint":"Count pairs satisfying both conditions.","explanation":"The favourable pairs are (H,2) and (H,4), out of 8 equally likely pairs: 2/8 = 1/4."},{"id":"PROB-004","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1004,"difficulty":"Easy","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A fair coin is tossed twice independently. Find P(exactly one Head).","choices":[{"id":"PROB-004-choice-5132a203","label":"A","text":"3/4"},{"id":"PROB-004-choice-d939926f","label":"B","text":"1/2"},{"id":"PROB-004-choice-f70b94ae","label":"C","text":"1/4"},{"id":"PROB-004-choice-6b86b273","label":"D","text":"1"}],"correctChoiceId":"PROB-004-choice-d939926f","hint":"Keep both possible positions of the Head.","explanation":"HT and TH are the 2 favourable outcomes among HH, HT, TH and TT. The probability is 2/4 = 1/2."},{"id":"PROB-005","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1005,"difficulty":"Easy","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"Two fair six-sided dice are rolled independently. Find P(the total is 2 OR the total is 12).","choices":[{"id":"PROB-005-choice-d8db7177","label":"A","text":"1/36"},{"id":"PROB-005-choice-47ba3574","label":"B","text":"1/12"},{"id":"PROB-005-choice-142bd7f8","label":"C","text":"1/18"},{"id":"PROB-005-choice-8f854692","label":"D","text":"1/6"}],"correctChoiceId":"PROB-005-choice-142bd7f8","hint":"The two totals cannot occur together.","explanation":"Only (1,1) and (6,6) work. There are 36 ordered outcomes, so 2/36 = 1/18."},{"id":"PROB-006","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1006,"difficulty":"Easy","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"A fair six-sided rune die is rolled once. A = an even number; B = a number greater than 4. Find P(A OR B). OR includes outcomes in both events.","choices":[{"id":"PROB-006-choice-d939926f","label":"A","text":"1/2"},{"id":"PROB-006-choice-0d7f0e33","label":"B","text":"1/3"},{"id":"PROB-006-choice-484aa6cc","label":"C","text":"2/3"},{"id":"PROB-006-choice-6527243b","label":"D","text":"5/6"}],"correctChoiceId":"PROB-006-choice-484aa6cc","hint":"Write the union without repeating 6.","explanation":"A = {2,4,6} and B = {5,6}. Their union is {2,4,5,6}, so the probability is 4/6 = 2/3."},{"id":"PROB-007","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1007,"difficulty":"Easy","curriculumStandards":["9.1.1"],"contextKind":"TEACHING_POOL","prompt":"A fair coin is tossed and a fair four-sided rune die numbered 1 to 4 is rolled independently. Which ordered outcome belongs to Heads AND a number greater than 2?","choices":[{"id":"PROB-007-choice-51c045a6","label":"A","text":"(H,2)"},{"id":"PROB-007-choice-595c3513","label":"B","text":"(T,3)"},{"id":"PROB-007-choice-2e1ea7d1","label":"C","text":"(H,3)"},{"id":"PROB-007-choice-d1a84728","label":"D","text":"(T,4)"}],"correctChoiceId":"PROB-007-choice-2e1ea7d1","hint":"Both parts of AND must be satisfied.","explanation":"(H,3) has a Head and a number greater than 2. Each other option breaks at least one condition."},{"id":"PROB-008","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1008,"difficulty":"Medium","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. Two distinct runes are drawn uniformly without replacement. Find P(both runes are blue).","choices":[{"id":"PROB-008-choice-9d5d5c10","label":"A","text":"1/10"},{"id":"PROB-008-choice-170f63c7","label":"B","text":"4/25"},{"id":"PROB-008-choice-bd82a28b","label":"C","text":"1/5"},{"id":"PROB-008-choice-0b9db2ec","label":"D","text":"2/5"}],"correctChoiceId":"PROB-008-choice-9d5d5c10","hint":"After one blue is drawn, update both counts.","explanation":"The probability is (2/5) × (1/4) = 1/10. The first rune is not put back."},{"id":"PROB-009","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1009,"difficulty":"Easy","curriculumStandards":["9.2.1"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. One rune is drawn, put back, and mixed before a second uniform draw. Are the events “first rune is red” and “second rune is red” independent?","choices":[{"id":"PROB-009-choice-5e738323","label":"A","text":"Independent: the second red chance stays 3/5."},{"id":"PROB-009-choice-dccbb284","label":"B","text":"Dependent: the second red chance becomes 2/4."},{"id":"PROB-009-choice-1acfac59","label":"C","text":"Mutually exclusive: two red draws are impossible."},{"id":"PROB-009-choice-0ae23565","label":"D","text":"Independent: the second red chance becomes 2/4."}],"correctChoiceId":"PROB-009-choice-5e738323","hint":"Check whether the first result changes the second chance.","explanation":"Replacement restores the same bag. P(second red | first red) = P(second red) = 3/5."},{"id":"PROB-010","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1010,"difficulty":"Easy","curriculumStandards":["9.2.1"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. Two uniform draws are made without replacement. Are the events “first rune is red” and “second rune is red” independent?","choices":[{"id":"PROB-010-choice-3640c508","label":"A","text":"Dependent: after a red first draw, the next red chance is 2/4."},{"id":"PROB-010-choice-91d0907b","label":"B","text":"Mutually exclusive: a red rune cannot follow a red rune."},{"id":"PROB-010-choice-f4c88f33","label":"C","text":"Dependent: after a red first draw, the next red chance is 3/4."},{"id":"PROB-010-choice-da664a06","label":"D","text":"Independent: the next red chance stays 3/5."}],"correctChoiceId":"PROB-010-choice-3640c508","hint":"Remove the first red rune from the bag.","explanation":"After a red first draw, 2 red runes remain among 4. Since 2/4 differs from 3/5, the events are dependent."},{"id":"PROB-011","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1011,"difficulty":"Easy","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. Two uniform draws are made with replacement and mixing after the first. Find P(red then blue).","choices":[{"id":"PROB-011-choice-088ae5cc","label":"A","text":"3/10"},{"id":"PROB-011-choice-0b9db2ec","label":"B","text":"2/5"},{"id":"PROB-011-choice-690916f7","label":"C","text":"6/25"},{"id":"PROB-011-choice-bd82a28b","label":"D","text":"1/5"}],"correctChoiceId":"PROB-011-choice-690916f7","hint":"Use the original bag for both draws.","explanation":"(3/5) × (2/5) = 6/25 because the first rune is put back."},{"id":"PROB-012","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1012,"difficulty":"Medium","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. Two uniform draws are made without replacement. Find P(red then blue).","choices":[{"id":"PROB-012-choice-bd82a28b","label":"A","text":"1/5"},{"id":"PROB-012-choice-088ae5cc","label":"B","text":"3/10"},{"id":"PROB-012-choice-d939926f","label":"C","text":"1/2"},{"id":"PROB-012-choice-690916f7","label":"D","text":"6/25"}],"correctChoiceId":"PROB-012-choice-088ae5cc","hint":"A red first draw leaves two blue runes among four.","explanation":"(3/5) × (2/4) = 6/20 = 3/10."},{"id":"PROB-013","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1013,"difficulty":"Medium","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. Two uniform draws are made without replacement. Find P(one red and one blue, in either order).","choices":[{"id":"PROB-013-choice-088ae5cc","label":"A","text":"3/10"},{"id":"PROB-013-choice-690916f7","label":"B","text":"6/25"},{"id":"PROB-013-choice-0b9db2ec","label":"C","text":"2/5"},{"id":"PROB-013-choice-e8692ca2","label":"D","text":"3/5"}],"correctChoiceId":"PROB-013-choice-e8692ca2","hint":"Add red-then-blue and blue-then-red.","explanation":"(3/5 × 2/4) + (2/5 × 3/4) = 3/10 + 3/10 = 3/5."},{"id":"PROB-014","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1014,"difficulty":"Medium","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 3 red runes and 2 blue runes. Two uniform draws are made without replacement. Find P(both runes have the same colour).","choices":[{"id":"PROB-014-choice-bd82a28b","label":"A","text":"1/5"},{"id":"PROB-014-choice-e8692ca2","label":"B","text":"3/5"},{"id":"PROB-014-choice-d0b0c5b0","label":"C","text":"13/25"},{"id":"PROB-014-choice-0b9db2ec","label":"D","text":"2/5"}],"correctChoiceId":"PROB-014-choice-0b9db2ec","hint":"Add the red-red and blue-blue branches.","explanation":"(3/5 × 2/4) + (2/5 × 1/4) = 3/10 + 1/10 = 2/5."},{"id":"PROB-015","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1015,"difficulty":"Medium","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"Two independent gates open with probabilities 3/4 and 2/3. Find P(both gates open).","choices":[{"id":"PROB-015-choice-d939926f","label":"A","text":"1/2"},{"id":"PROB-015-choice-426cc2a5","label":"B","text":"17/12"},{"id":"PROB-015-choice-47ba3574","label":"C","text":"1/12"},{"id":"PROB-015-choice-844f5767","label":"D","text":"5/12"}],"correctChoiceId":"PROB-015-choice-d939926f","hint":"Multiply the probabilities of independent events.","explanation":"(3/4) × (2/3) = 6/12 = 1/2."},{"id":"PROB-016","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1016,"difficulty":"Medium","curriculumStandards":["9.2.3"],"contextKind":"TEACHING_POOL","prompt":"Two independent gates open with probabilities 3/4 and 2/3. Find P(exactly one gate opens).","choices":[{"id":"PROB-016-choice-844f5767","label":"A","text":"5/12"},{"id":"PROB-016-choice-47ba3574","label":"B","text":"1/12"},{"id":"PROB-016-choice-13f7b6ab","label":"C","text":"11/12"},{"id":"PROB-016-choice-d939926f","label":"D","text":"1/2"}],"correctChoiceId":"PROB-016-choice-844f5767","hint":"Use open-shut and shut-open as separate branches.","explanation":"(3/4 × 1/3) + (1/4 × 2/3) = 1/4 + 1/6 = 5/12."},{"id":"PROB-017","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1017,"difficulty":"Medium","curriculumStandards":["9.2.2"],"contextKind":"TEACHING_POOL","prompt":"Events A and B have P(A)=1/2, P(B)=1/3 and P(A AND B)=1/6. Are A and B independent?","choices":[{"id":"PROB-017-choice-86a99a97","label":"A","text":"No, because P(A) and P(B) are different."},{"id":"PROB-017-choice-7ba9d795","label":"B","text":"No, because independent events cannot overlap."},{"id":"PROB-017-choice-db563fb9","label":"C","text":"Yes, because P(A) + P(B) = 1."},{"id":"PROB-017-choice-05ad4ac6","label":"D","text":"Yes, because P(A AND B) = P(A) × P(B)."}],"correctChoiceId":"PROB-017-choice-05ad4ac6","hint":"Compare the intersection with the product.","explanation":"(1/2) × (1/3) = 1/6, which matches the given intersection. This is the independence test."},{"id":"PROB-018","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1018,"difficulty":"Medium","curriculumStandards":["9.2.2"],"contextKind":"TEACHING_POOL","prompt":"Events A and B have P(A)=1/2, P(B)=1/3 and P(A AND B)=1/4. Which conclusion is correct?","choices":[{"id":"PROB-018-choice-833936c6","label":"A","text":"They are independent because both can happen."},{"id":"PROB-018-choice-e2632a71","label":"B","text":"They are dependent because 1/4 is not (1/2) × (1/3)."},{"id":"PROB-018-choice-42c182fd","label":"C","text":"They are mutually exclusive because 1/4 is positive."},{"id":"PROB-018-choice-495cb646","label":"D","text":"They are independent because 1/2 + 1/3 is less than 1."}],"correctChoiceId":"PROB-018-choice-e2632a71","hint":"Independence requires equality with the product.","explanation":"The product is 1/6, not 1/4. Their overlap also means they are not mutually exclusive."},{"id":"PROB-019","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1019,"difficulty":"Easy","curriculumStandards":["9.2.1"],"contextKind":"TEACHING_POOL","prompt":"A fair six-sided rune die is rolled once. A = an even number; B = a number greater than 3. Are A and B independent?","choices":[{"id":"PROB-019-choice-2d814f0d","label":"A","text":"Yes: both probabilities are 1/2."},{"id":"PROB-019-choice-0ce91b93","label":"B","text":"No: P(A AND B)=1/3, but P(A)P(B)=1/4."},{"id":"PROB-019-choice-476e6b96","label":"C","text":"No: A and B are mutually exclusive."},{"id":"PROB-019-choice-df673fbd","label":"D","text":"Yes: A and B share two outcomes."}],"correctChoiceId":"PROB-019-choice-0ce91b93","hint":"Compare {4,6} with the product of the two half-probabilities.","explanation":"A = {2,4,6}, B = {4,5,6}, and their intersection is {4,6}. Thus 1/3 differs from 1/4."},{"id":"PROB-020","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1020,"difficulty":"Easy","curriculumStandards":["9.2.1"],"contextKind":"TEACHING_POOL","prompt":"Which experiment makes “first result is Heads” and “second result is Heads” independent?","choices":[{"id":"PROB-020-choice-f9d66b43","label":"A","text":"Drawing twice without replacement from a bag with three H runes and two T runes."},{"id":"PROB-020-choice-5cfb978f","label":"B","text":"Drawing twice without replacement from a bag with two H runes and one T rune."},{"id":"PROB-020-choice-d26ca9c3","label":"C","text":"Drawing twice without replacement from a bag with one H rune and one T rune."},{"id":"PROB-020-choice-6039ea85","label":"D","text":"Tossing a fair coin twice, with each toss independent."}],"correctChoiceId":"PROB-020-choice-6039ea85","hint":"Look for an unchanged second probability.","explanation":"Independent coin tosses keep P(Heads)=1/2. In each listed mixed bag, removing a Head changes the second Head probability."},{"id":"PROB-021","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1021,"difficulty":"Easy","curriculumStandards":["9.3.1"],"contextKind":"TEACHING_POOL","prompt":"One card is selected from a teaching pool. Every card has exactly one category: Attack, Guard or Skill. Are “Attack” and “Guard” mutually exclusive for this single selection?","choices":[{"id":"PROB-021-choice-27305843","label":"A","text":"No: mutually exclusive events must be independent."},{"id":"PROB-021-choice-49ea8cd5","label":"B","text":"Yes: their probabilities must be equal."},{"id":"PROB-021-choice-f4f48710","label":"C","text":"Yes: one card cannot have both categories."},{"id":"PROB-021-choice-f19f65f6","label":"D","text":"No: different cards can be drawn on different turns."}],"correctChoiceId":"PROB-021-choice-f4f48710","hint":"Use the stated one-category rule for one selection.","explanation":"The categories cannot overlap on a single selected card, so their intersection is empty."},{"id":"PROB-022","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1022,"difficulty":"Easy","curriculumStandards":["9.3.1"],"contextKind":"TEACHING_POOL","prompt":"A 12-card teaching pool has 8 Attack cards, including 3 Fire cards. The remaining 4 cards are not Attack. One card is selected uniformly. Are “Attack” and “Fire” mutually exclusive?","choices":[{"id":"PROB-022-choice-4706050d","label":"A","text":"No: all 3 Fire cards are also Attack cards."},{"id":"PROB-022-choice-1c21af2f","label":"B","text":"Yes: a card cannot be in two events."},{"id":"PROB-022-choice-e5a80f9a","label":"C","text":"No: they must therefore be independent."},{"id":"PROB-022-choice-11526dfb","label":"D","text":"Yes: Attack and Fire are different words."}],"correctChoiceId":"PROB-022-choice-4706050d","hint":"An element may belong to two events.","explanation":"The intersection contains the 3 Fire cards, so it is not empty. Overlap does not establish independence."},{"id":"PROB-023","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1023,"difficulty":"Easy","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"A 12-card teaching pool has 8 Attack cards, including 3 Fire cards. The other 4 cards are not Attack. One card is selected uniformly. Find P(Attack OR Fire).","choices":[{"id":"PROB-023-choice-484aa6cc","label":"A","text":"2/3"},{"id":"PROB-023-choice-844f5767","label":"B","text":"5/12"},{"id":"PROB-023-choice-f70b94ae","label":"C","text":"1/4"},{"id":"PROB-023-choice-13f7b6ab","label":"D","text":"11/12"}],"correctChoiceId":"PROB-023-choice-484aa6cc","hint":"Fire is already inside Attack.","explanation":"Attack ∪ Fire is just Attack. Therefore the probability is 8/12 = 2/3."},{"id":"PROB-024","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1024,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching pool has 12 distinct cards: 8 Attack, 2 Guard and 2 Skill. Each card has exactly one category. One card is selected uniformly. Find P(Attack OR Guard).","choices":[{"id":"PROB-024-choice-484aa6cc","label":"A","text":"2/3"},{"id":"PROB-024-choice-8f854692","label":"B","text":"1/6"},{"id":"PROB-024-choice-6527243b","label":"C","text":"5/6"},{"id":"PROB-024-choice-0d7f0e33","label":"D","text":"1/3"}],"correctChoiceId":"PROB-024-choice-6527243b","hint":"Add the counts of the disjoint categories.","explanation":"There are 8 + 2 = 10 favourable cards among 12, giving 10/12 = 5/6."},{"id":"PROB-025","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1025,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"In a teaching pool of 20 distinct cards, 9 carry a red mark, 8 carry a rune mark, and 3 carry both. One card is selected uniformly. Find P(red OR rune).","choices":[{"id":"PROB-025-choice-2d438214","label":"A","text":"11/20"},{"id":"PROB-025-choice-d21e521c","label":"B","text":"17/20"},{"id":"PROB-025-choice-1a3d28e3","label":"C","text":"3/20"},{"id":"PROB-025-choice-9e3ee503","label":"D","text":"7/10"}],"correctChoiceId":"PROB-025-choice-9e3ee503","hint":"Subtract the overlap once.","explanation":"(9 + 8 − 3)/20 = 14/20 = 7/10."},{"id":"PROB-026","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1026,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"In a teaching pool of 20 distinct cards, 9 carry a red mark, 8 carry a rune mark, and 3 carry both. One card is selected uniformly. Find P(neither red nor rune).","choices":[{"id":"PROB-026-choice-9e3ee503","label":"A","text":"7/10"},{"id":"PROB-026-choice-088ae5cc","label":"B","text":"3/10"},{"id":"PROB-026-choice-d21e521c","label":"C","text":"17/20"},{"id":"PROB-026-choice-1a3d28e3","label":"D","text":"3/20"}],"correctChoiceId":"PROB-026-choice-088ae5cc","hint":"First find the union, then take its complement.","explanation":"The union contains 14 cards. The remaining 20 − 14 = 6 cards give 6/20 = 3/10."},{"id":"PROB-027","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1027,"difficulty":"Medium","curriculumStandards":["9.3.2"],"contextKind":"TEACHING_POOL","prompt":"For events A and B, P(A)=3/5, P(B)=1/2 and P(A OR B)=4/5. Find P(A AND B).","choices":[{"id":"PROB-027-choice-9d5d5c10","label":"A","text":"1/10"},{"id":"PROB-027-choice-bd82a28b","label":"B","text":"1/5"},{"id":"PROB-027-choice-088ae5cc","label":"C","text":"3/10"},{"id":"PROB-027-choice-9e3ee503","label":"D","text":"7/10"}],"correctChoiceId":"PROB-027-choice-088ae5cc","hint":"Rearrange the union formula.","explanation":"P(A AND B) = 3/5 + 1/2 − 4/5 = 3/10."},{"id":"PROB-028","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1028,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"Mutually exclusive events A and B have P(A)=2/7 and P(B)=3/7. Find P(A OR B).","choices":[{"id":"PROB-028-choice-2da190e5","label":"A","text":"1/7"},{"id":"PROB-028-choice-a524479d","label":"B","text":"5/7"},{"id":"PROB-028-choice-382ede73","label":"C","text":"6/49"},{"id":"PROB-028-choice-6b86b273","label":"D","text":"1"}],"correctChoiceId":"PROB-028-choice-a524479d","hint":"Mutually exclusive events have no overlap.","explanation":"The intersection is zero, so P(A OR B) = 2/7 + 3/7 = 5/7."},{"id":"PROB-029","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1029,"difficulty":"Hard","curriculumStandards":["9.2.2","9.3.1"],"contextKind":"TEACHING_POOL","prompt":"Mutually exclusive events A and B have P(A)=2/7 and P(B)=3/7. Are they independent?","choices":[{"id":"PROB-029-choice-a3d1dab9","label":"A","text":"No: their intersection is 0, but their probability product is 6/49."},{"id":"PROB-029-choice-a44d1391","label":"B","text":"No: mutually exclusive events must have equal probabilities."},{"id":"PROB-029-choice-4be44c49","label":"C","text":"Yes: all mutually exclusive events are independent."},{"id":"PROB-029-choice-ee7e9a68","label":"D","text":"Yes: the sum is less than 1."}],"correctChoiceId":"PROB-029-choice-a3d1dab9","hint":"Compare a zero intersection with a nonzero product.","explanation":"Independence requires P(A AND B)=P(A)P(B). Here 0 ≠ 6/49, so they are dependent."},{"id":"PROB-030","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1030,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"A number is selected uniformly from 1 to 12. A = a multiple of 3; B = a multiple of 4. Find P(A OR B).","choices":[{"id":"PROB-030-choice-2d0ba250","label":"A","text":"7/12"},{"id":"PROB-030-choice-d939926f","label":"B","text":"1/2"},{"id":"PROB-030-choice-844f5767","label":"C","text":"5/12"},{"id":"PROB-030-choice-47ba3574","label":"D","text":"1/12"}],"correctChoiceId":"PROB-030-choice-d939926f","hint":"The number 12 lies in both events.","explanation":"The union is {3,4,6,8,9,12}, containing 6 of the 12 numbers. The probability is 1/2."},{"id":"PROB-031","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1031,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"A fair six-sided rune die is rolled once. A = a prime number; B = an even number. Find P(A OR B).","choices":[{"id":"PROB-031-choice-6b86b273","label":"A","text":"1"},{"id":"PROB-031-choice-8f854692","label":"B","text":"1/6"},{"id":"PROB-031-choice-484aa6cc","label":"C","text":"2/3"},{"id":"PROB-031-choice-6527243b","label":"D","text":"5/6"}],"correctChoiceId":"PROB-031-choice-6527243b","hint":"Remember that 2 is prime and even.","explanation":"A = {2,3,5}; B = {2,4,6}. Their union is {2,3,4,5,6}, giving 5/6."},{"id":"PROB-032","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1032,"difficulty":"Medium","curriculumStandards":["9.3.3"],"contextKind":"TEACHING_POOL","prompt":"A teaching pool has 10 distinct cards: 4 Fire cards, 3 Ice cards and 3 Neutral cards. Each card has exactly one of these marks. One card is selected uniformly. Find P(Fire OR Ice).","choices":[{"id":"PROB-032-choice-088ae5cc","label":"A","text":"3/10"},{"id":"PROB-032-choice-9d5d5c10","label":"B","text":"1/10"},{"id":"PROB-032-choice-fe6e83cd","label":"C","text":"3/25"},{"id":"PROB-032-choice-9e3ee503","label":"D","text":"7/10"}],"correctChoiceId":"PROB-032-choice-9e3ee503","hint":"The two marks have no overlap.","explanation":"There are 4 + 3 = 7 favourable cards among 10, so the probability is 7/10."},{"id":"PROB-033","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1033,"difficulty":"Medium","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"A fair coin is tossed 3 times independently. Find P(at least one Head).","choices":[{"id":"PROB-033-choice-52e90ae2","label":"A","text":"1/8"},{"id":"PROB-033-choice-fc5755dd","label":"B","text":"7/8"},{"id":"PROB-033-choice-d939926f","label":"C","text":"1/2"},{"id":"PROB-033-choice-896af017","label":"D","text":"3/8"}],"correctChoiceId":"PROB-033-choice-fc5755dd","hint":"Use the complement of no Heads.","explanation":"Only TTT has no Heads among the 8 equally likely outcomes. Therefore 1 − 1/8 = 7/8."},{"id":"PROB-034","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1034,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"A fair coin is tossed 3 times independently. Find P(exactly two Heads).","choices":[{"id":"PROB-034-choice-d939926f","label":"A","text":"1/2"},{"id":"PROB-034-choice-52e90ae2","label":"B","text":"1/8"},{"id":"PROB-034-choice-896af017","label":"C","text":"3/8"},{"id":"PROB-034-choice-f70b94ae","label":"D","text":"1/4"}],"correctChoiceId":"PROB-034-choice-896af017","hint":"List the possible position of the one Tail.","explanation":"HHT, HTH and THH are the 3 favourable outcomes out of 8. The probability is 3/8."},{"id":"PROB-035","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1035,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 4 gold runes and 2 silver runes. Three uniform draws are made without replacement. Find P(all three runes are gold).","choices":[{"id":"PROB-035-choice-78f3b00a","label":"A","text":"8/27"},{"id":"PROB-035-choice-3d9e0949","label":"B","text":"2/15"},{"id":"PROB-035-choice-0d7f0e33","label":"C","text":"1/3"},{"id":"PROB-035-choice-bd82a28b","label":"D","text":"1/5"}],"correctChoiceId":"PROB-035-choice-bd82a28b","hint":"Update the gold count and total after each draw.","explanation":"(4/6) × (3/5) × (2/4) = 24/120 = 1/5."},{"id":"PROB-036","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1036,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"A teaching bag contains 4 gold runes and 2 silver runes. Three uniform draws are made with replacement and mixing after every draw. Find P(exactly two gold runes).","choices":[{"id":"PROB-036-choice-185b24d9","label":"A","text":"2/9"},{"id":"PROB-036-choice-2b4a3397","label":"B","text":"4/9"},{"id":"PROB-036-choice-78f3b00a","label":"C","text":"8/27"},{"id":"PROB-036-choice-484aa6cc","label":"D","text":"2/3"}],"correctChoiceId":"PROB-036-choice-2b4a3397","hint":"There are three possible positions for the silver result.","explanation":"Each order with two gold and one silver has probability (2/3)² × (1/3) = 4/27. There are 3 orders, so 12/27 = 4/9."},{"id":"PROB-037","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1037,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"Three independent gates each open with probability 4/5. Find P(at least one gate fails to open).","choices":[{"id":"PROB-037-choice-8636383b","label":"A","text":"61/125"},{"id":"PROB-037-choice-e8692ca2","label":"B","text":"3/5"},{"id":"PROB-037-choice-cb57a137","label":"C","text":"1/125"},{"id":"PROB-037-choice-652915e0","label":"D","text":"64/125"}],"correctChoiceId":"PROB-037-choice-8636383b","hint":"Subtract the probability that all three open from 1.","explanation":"P(all open)=(4/5)³=64/125. Therefore P(at least one fails)=1−64/125=61/125."},{"id":"PROB-038","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1038,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"A teaching pool has 8 distinct cards, x of which are marked Fire. Two uniform draws are made without replacement. P(both cards are Fire)=3/14. What is x?","choices":[{"id":"PROB-038-choice-e7f6c011","label":"A","text":"6"},{"id":"PROB-038-choice-ef2d127d","label":"B","text":"5"},{"id":"PROB-038-choice-4b227777","label":"C","text":"4"},{"id":"PROB-038-choice-4e074085","label":"D","text":"3"}],"correctChoiceId":"PROB-038-choice-4b227777","hint":"Test whole-number counts using x/8 × (x−1)/7.","explanation":"x(x−1)/56=3/14 gives x(x−1)=12. The count x=4 works: 4×3=12."},{"id":"PROB-039","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1039,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"Two teaching bags each contain 2 red and 1 blue rune. Bag A: draw twice with replacement. Bag B: draw twice without replacement. All draws are uniform. Which bag gives the greater P(both red)?","choices":[{"id":"PROB-039-choice-9c2915a0","label":"A","text":"Both bags: 4/9."},{"id":"PROB-039-choice-52454189","label":"B","text":"Bag B: 4/9, compared with Bag A: 1/3."},{"id":"PROB-039-choice-12341527","label":"C","text":"Both bags: 1/3."},{"id":"PROB-039-choice-a06f7508","label":"D","text":"Bag A: 4/9, compared with Bag B: 1/3."}],"correctChoiceId":"PROB-039-choice-a06f7508","hint":"Work out each experiment separately.","explanation":"Bag A gives (2/3)²=4/9. Bag B gives (2/3)(1/2)=1/3. Since 4/9>1/3, Bag A is greater."},{"id":"PROB-040","topicId":"T1","topicCode":"PROB","chapter":9,"topic":"Probability of Combined Events","seed":1040,"difficulty":"Hard","curriculumStandards":["9.4.1"],"contextKind":"TEACHING_POOL","prompt":"A teaching pool has 5 distinct cards: 2 Attack and 3 Guard. Two uniform draws are made without replacement. Find P(at least one Attack).","choices":[{"id":"PROB-040-choice-00a49fc7","label":"A","text":"16/25"},{"id":"PROB-040-choice-088ae5cc","label":"B","text":"3/10"},{"id":"PROB-040-choice-0b9db2ec","label":"C","text":"2/5"},{"id":"PROB-040-choice-9e3ee503","label":"D","text":"7/10"}],"correctChoiceId":"PROB-040-choice-9e3ee503","hint":"The complement is two Guard cards.","explanation":"P(two Guard)=(3/5)(2/4)=3/10. Hence P(at least one Attack)=1−3/10=7/10."},{"id":"SET-001","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2001,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={1,2,3,4} and B={3,4,5,6}. Find A ∩ B.","choices":[{"id":"SET-001-choice-224d736d","label":"A","text":"{1, 2, 3, 4, 5, 6}"},{"id":"SET-001-choice-c55e2043","label":"B","text":"{3, 4}"},{"id":"SET-001-choice-73c8ffe9","label":"C","text":"∅"},{"id":"SET-001-choice-129d9821","label":"D","text":"{1, 2, 5, 6}"}],"correctChoiceId":"SET-001-choice-c55e2043","hint":"Keep elements that occur in both sets.","explanation":"Only 3 and 4 belong to both A and B."},{"id":"SET-002","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2002,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={2,4,6,8}, B={1,2,4,7} and C={3,4,5}. Find A ∩ B ∩ C.","choices":[{"id":"SET-002-choice-79bc9b35","label":"A","text":"{4}"},{"id":"SET-002-choice-ffcaea4e","label":"B","text":"{2, 4}"},{"id":"SET-002-choice-02e613a4","label":"C","text":"{3, 4, 5}"},{"id":"SET-002-choice-73c8ffe9","label":"D","text":"∅"}],"correctChoiceId":"SET-002-choice-79bc9b35","hint":"Check membership in all three sets.","explanation":"A ∩ B={2,4}. Only 4 from this intersection also belongs to C."},{"id":"SET-003","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2003,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={2,4} and B={1,2,3,4,5}. Find A ∩ B.","choices":[{"id":"SET-003-choice-da75b8d3","label":"A","text":"{1, 2, 3, 4, 5}"},{"id":"SET-003-choice-6000be55","label":"B","text":"{1, 3, 5}"},{"id":"SET-003-choice-ffcaea4e","label":"C","text":"{2, 4}"},{"id":"SET-003-choice-73c8ffe9","label":"D","text":"∅"}],"correctChoiceId":"SET-003-choice-ffcaea4e","hint":"Every element of A is already in B.","explanation":"A is a subset of B. Therefore A ∩ B=A={2,4}."},{"id":"SET-004","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2004,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={1,3,5} and B={2,4,6}. Find A ∩ B.","choices":[{"id":"SET-004-choice-224d736d","label":"A","text":"{1, 2, 3, 4, 5, 6}"},{"id":"SET-004-choice-a0064450","label":"B","text":"{0}"},{"id":"SET-004-choice-73c8ffe9","label":"C","text":"∅"},{"id":"SET-004-choice-6000be55","label":"D","text":"{1, 3, 5}"}],"correctChoiceId":"SET-004-choice-73c8ffe9","hint":"Look for shared elements, not nearby numbers.","explanation":"The sets have no shared elements. The empty set is ∅; it is not the set {0}."},{"id":"SET-005","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2005,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,...,18}. A is the set of even numbers in U. B is the set of multiples of 3 in U. Find A ∩ B.","choices":[{"id":"SET-005-choice-e8cf5ed3","label":"A","text":"{3, 6, 9, 12, 15, 18}"},{"id":"SET-005-choice-87e1daa6","label":"B","text":"{2, 4, 6, 8, 10, 12, 14, 16, 18}"},{"id":"SET-005-choice-1a4b98ca","label":"C","text":"{6, 12, 18}"},{"id":"SET-005-choice-b71b7461","label":"D","text":"{6, 12}"}],"correctChoiceId":"SET-005-choice-1a4b98ca","hint":"An element must be even and divisible by 3.","explanation":"The numbers satisfying both conditions are the multiples of 6 in U: 6, 12 and 18."},{"id":"SET-006","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2006,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Each teaching card has a unique ID. Fire cards F={c1,c2,c5}; Attack cards A={c1,c3,c5,c6}. Which set lists the Fire cards that are also Attack cards?","choices":[{"id":"SET-006-choice-05bdc640","label":"A","text":"{c1, c5}"},{"id":"SET-006-choice-0324858c","label":"B","text":"{c3, c6}"},{"id":"SET-006-choice-d95c2161","label":"C","text":"{c1, c2, c3, c5, c6}"},{"id":"SET-006-choice-9b028473","label":"D","text":"{c2}"}],"correctChoiceId":"SET-006-choice-05bdc640","hint":"Compare card IDs in both lists.","explanation":"c1 and c5 occur in both F and A. The set elements are physical card IDs."},{"id":"SET-007","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2007,"difficulty":"Easy","curriculumStandards":["4.1.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7,8}, A={1,2,3,4} and B={3,4,5}. A prime mark denotes complement in U. Find (A ∩ B)′.","choices":[{"id":"SET-007-choice-e2afef06","label":"A","text":"{1, 2, 5, 6, 7, 8}"},{"id":"SET-007-choice-c55e2043","label":"B","text":"{3, 4}"},{"id":"SET-007-choice-1b95eb3e","label":"C","text":"{6, 7, 8}"},{"id":"SET-007-choice-da75b8d3","label":"D","text":"{1, 2, 3, 4, 5}"}],"correctChoiceId":"SET-007-choice-e2afef06","hint":"Find the intersection, then remove it from U.","explanation":"A ∩ B={3,4}. Its complement in U contains all the other elements."},{"id":"SET-008","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2008,"difficulty":"Easy","curriculumStandards":["4.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"In a group of adventurers, A∩B={Lina, Omar, Suri, Wei}. Here A means owns a map and B means owns a lantern. How many adventurers own both?","choices":[{"id":"SET-008-choice-4b227777","label":"A","text":"4"},{"id":"SET-008-choice-2c624232","label":"B","text":"8"},{"id":"SET-008-choice-d4735e3a","label":"C","text":"2"},{"id":"SET-008-choice-4e074085","label":"D","text":"3"}],"correctChoiceId":"SET-008-choice-4b227777","hint":"Count the elements in the given intersection.","explanation":"There are four different names in A ∩ B, so n(A ∩ B)=4."},{"id":"SET-009","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2009,"difficulty":"Easy","curriculumStandards":["4.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A is the set of rooms with a chest. B is the set of rooms with a blue door. Which description matches A ∩ B?","choices":[{"id":"SET-009-choice-9fff74f3","label":"A","text":"Rooms with a chest but no blue door."},{"id":"SET-009-choice-3b09d7a2","label":"B","text":"Rooms with both a chest and a blue door."},{"id":"SET-009-choice-a20db8ef","label":"C","text":"Rooms with a chest or a blue door or both."},{"id":"SET-009-choice-ba1c33ee","label":"D","text":"Rooms with neither feature."}],"correctChoiceId":"SET-009-choice-3b09d7a2","hint":"Intersection requires both properties.","explanation":"A room belongs to A ∩ B only when it belongs to A and to B."},{"id":"SET-010","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2010,"difficulty":"Medium","curriculumStandards":["4.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,...,15}. A contains the multiples of 2 in U and B contains the multiples of 5 in U. How many numbers belong to A ∩ B?","choices":[{"id":"SET-010-choice-d4735e3a","label":"A","text":"2"},{"id":"SET-010-choice-4b227777","label":"B","text":"4"},{"id":"SET-010-choice-4e074085","label":"C","text":"3"},{"id":"SET-010-choice-6b86b273","label":"D","text":"1"}],"correctChoiceId":"SET-010-choice-6b86b273","hint":"Look for multiples of both 2 and 5 inside U.","explanation":"Only 10 is divisible by both 2 and 5 in this universe. Thus n(A ∩ B)=1."},{"id":"SET-011","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2011,"difficulty":"Easy","curriculumStandards":["4.2.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={1,2,3} and B={3,4,5}. Find A ∪ B.","choices":[{"id":"SET-011-choice-3dcfe357","label":"A","text":"{1, 2, 4, 5}"},{"id":"SET-011-choice-c7401b91","label":"B","text":"{3}"},{"id":"SET-011-choice-da75b8d3","label":"C","text":"{1, 2, 3, 4, 5}"},{"id":"SET-011-choice-73c8ffe9","label":"D","text":"∅"}],"correctChoiceId":"SET-011-choice-da75b8d3","hint":"Combine the sets and list shared elements once.","explanation":"The union contains every element in A or B, with no duplicates."},{"id":"SET-012","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2012,"difficulty":"Easy","curriculumStandards":["4.2.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={2,6} and B={1,2,3,6,8}. Find A ∪ B.","choices":[{"id":"SET-012-choice-b4ab5e3a","label":"A","text":"{1, 3, 8}"},{"id":"SET-012-choice-cf6b75cb","label":"B","text":"{1, 2, 3, 6, 8}"},{"id":"SET-012-choice-73c8ffe9","label":"C","text":"∅"},{"id":"SET-012-choice-e010274a","label":"D","text":"{2, 6}"}],"correctChoiceId":"SET-012-choice-cf6b75cb","hint":"A adds no new element because A is a subset of B.","explanation":"Since A⊆B, the union is B."},{"id":"SET-013","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2013,"difficulty":"Easy","curriculumStandards":["4.2.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={a,c,e} and B={b,d}. Find A ∪ B.","choices":[{"id":"SET-013-choice-28fc34b1","label":"A","text":"{a, c, e}"},{"id":"SET-013-choice-73c8ffe9","label":"B","text":"∅"},{"id":"SET-013-choice-4f6668ec","label":"C","text":"{a, b, c, d, e}"},{"id":"SET-013-choice-3118ac62","label":"D","text":"{b, d}"}],"correctChoiceId":"SET-013-choice-4f6668ec","hint":"Union includes elements from either set.","explanation":"All five different letters belong to the union."},{"id":"SET-014","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2014,"difficulty":"Easy","curriculumStandards":["4.2.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={2,4,8}. Find A ∪ ∅.","choices":[{"id":"SET-014-choice-611c27ae","label":"A","text":"{2, 4, 8}"},{"id":"SET-014-choice-ffcaea4e","label":"B","text":"{2, 4}"},{"id":"SET-014-choice-442fa0d2","label":"C","text":"{0, 2, 4, 8}"},{"id":"SET-014-choice-73c8ffe9","label":"D","text":"∅"}],"correctChoiceId":"SET-014-choice-611c27ae","hint":"The empty set contributes no elements.","explanation":"Taking the union with the empty set leaves A unchanged."},{"id":"SET-015","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2015,"difficulty":"Easy","curriculumStandards":["4.2.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7}, A={1,3,5} and B={2,3,6}. Complements are taken in U. Find (A ∪ B)′.","choices":[{"id":"SET-015-choice-e97f855d","label":"A","text":"{4, 7}"},{"id":"SET-015-choice-c7401b91","label":"B","text":"{3}"},{"id":"SET-015-choice-796b3da4","label":"C","text":"{1, 2, 3, 5, 6}"},{"id":"SET-015-choice-73bbffe5","label":"D","text":"{1, 2, 4, 5, 6, 7}"}],"correctChoiceId":"SET-015-choice-e97f855d","hint":"Remove the full union from U.","explanation":"A ∪ B={1,2,3,5,6}. Only 4 and 7 remain in U."},{"id":"SET-016","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2016,"difficulty":"Medium","curriculumStandards":["4.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A guild has 30 members. 18 own a map, 14 own a lantern and 8 own both. How many own neither?","choices":[{"id":"SET-016-choice-4b227777","label":"A","text":"4"},{"id":"SET-016-choice-e7f6c011","label":"B","text":"6"},{"id":"SET-016-choice-2c624232","label":"C","text":"8"},{"id":"SET-016-choice-c2356069","label":"D","text":"24"}],"correctChoiceId":"SET-016-choice-e7f6c011","hint":"Count the union before counting those outside it.","explanation":"Map or lantern: 18+14−8=24 members. Neither: 30−24=6."},{"id":"SET-017","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2017,"difficulty":"Medium","curriculumStandards":["4.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"For two finite sets, n(A)=13, n(B)=11 and n(A ∩ B)=5. Find n(A ∪ B).","choices":[{"id":"SET-017-choice-c2356069","label":"A","text":"24"},{"id":"SET-017-choice-35135aaa","label":"B","text":"29"},{"id":"SET-017-choice-e7f6c011","label":"C","text":"6"},{"id":"SET-017-choice-9400f1b2","label":"D","text":"19"}],"correctChoiceId":"SET-017-choice-9400f1b2","hint":"The overlap was included in both set counts.","explanation":"n(A ∪ B)=13+11−5=19."},{"id":"SET-018","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2018,"difficulty":"Medium","curriculumStandards":["4.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"For two finite sets, n(A)=16, n(B)=12 and n(A ∪ B)=21. Find n(A ∩ B).","choices":[{"id":"SET-018-choice-ef2d127d","label":"A","text":"5"},{"id":"SET-018-choice-7902699b","label":"B","text":"7"},{"id":"SET-018-choice-59e19706","label":"C","text":"28"},{"id":"SET-018-choice-19581e27","label":"D","text":"9"}],"correctChoiceId":"SET-018-choice-7902699b","hint":"Rearrange the formula for the union count.","explanation":"n(A ∩ B)=16+12−21=7."},{"id":"SET-019","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2019,"difficulty":"Medium","curriculumStandards":["4.2.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={1,4}, B={2,4,6} and C={3,6}. Find A ∪ B ∪ C.","choices":[{"id":"SET-019-choice-42854fb4","label":"A","text":"{1, 2, 3, 4}"},{"id":"SET-019-choice-11f95d8d","label":"B","text":"{1, 2, 3, 4, 6}"},{"id":"SET-019-choice-13ccb4bc","label":"C","text":"{4, 6}"},{"id":"SET-019-choice-73c8ffe9","label":"D","text":"∅"}],"correctChoiceId":"SET-019-choice-11f95d8d","hint":"Include every distinct element found in any of the three sets.","explanation":"The combined list is 1, 2, 3, 4 and 6. Repeated elements are listed once."},{"id":"SET-020","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2020,"difficulty":"Easy","curriculumStandards":["4.2.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6}, A={1,3,5} and B={2,4,6}. Complements are taken in U. Find (A ∪ B)′.","choices":[{"id":"SET-020-choice-6000be55","label":"A","text":"{1, 3, 5}"},{"id":"SET-020-choice-73c8ffe9","label":"B","text":"∅"},{"id":"SET-020-choice-a0064450","label":"C","text":"{0}"},{"id":"SET-020-choice-224d736d","label":"D","text":"{1, 2, 3, 4, 5, 6}"}],"correctChoiceId":"SET-020-choice-73c8ffe9","hint":"First check whether the union equals the whole universe.","explanation":"A ∪ B=U. Nothing in U lies outside the union, so its complement is empty."},{"id":"SET-021","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2021,"difficulty":"Medium","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6}, A={1,2,3,4} and B={3,4,5}. Complements are taken in U. Find A ∩ B′.","choices":[{"id":"SET-021-choice-7bb8408f","label":"A","text":"{1, 2, 6}"},{"id":"SET-021-choice-2e38cc51","label":"B","text":"{5, 6}"},{"id":"SET-021-choice-26a90b8c","label":"C","text":"{1, 2}"},{"id":"SET-021-choice-c55e2043","label":"D","text":"{3, 4}"}],"correctChoiceId":"SET-021-choice-26a90b8c","hint":"Keep elements in A that are not in B.","explanation":"B′={1,2,6}. Its intersection with A is {1,2}."},{"id":"SET-022","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2022,"difficulty":"Medium","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={1,2,3}, B={3,4,5} and C={2,5,6}. Find (A ∪ B) ∩ C.","choices":[{"id":"SET-022-choice-c7401b91","label":"A","text":"{3}"},{"id":"SET-022-choice-6088233c","label":"B","text":"{2, 5, 6}"},{"id":"SET-022-choice-0eb24be4","label":"C","text":"{2, 5}"},{"id":"SET-022-choice-c6207456","label":"D","text":"{1, 2, 3, 5}"}],"correctChoiceId":"SET-022-choice-0eb24be4","hint":"Do the operation inside the brackets first.","explanation":"A ∪ B={1,2,3,4,5}. The elements of C also in this union are 2 and 5."},{"id":"SET-023","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2023,"difficulty":"Medium","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A={1,2,3}, B={3,4,5} and C={2,5,6}. Find A ∪ (B ∩ C).","choices":[{"id":"SET-023-choice-0eb24be4","label":"A","text":"{2, 5}"},{"id":"SET-023-choice-796b3da4","label":"B","text":"{1, 2, 3, 5, 6}"},{"id":"SET-023-choice-da75b8d3","label":"C","text":"{1, 2, 3, 4, 5}"},{"id":"SET-023-choice-c6207456","label":"D","text":"{1, 2, 3, 5}"}],"correctChoiceId":"SET-023-choice-c6207456","hint":"The brackets make the intersection come first.","explanation":"B ∩ C={5}. Adding this to A gives {1,2,3,5}."},{"id":"SET-024","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2024,"difficulty":"Medium","curriculumStandards":["4.3.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7}, A={1,2,3}, B={2,3,4} and C={1,3,5,7}. Complements are taken in U. Find (A ∩ B)′ ∩ C.","choices":[{"id":"SET-024-choice-c7401b91","label":"A","text":"{3}"},{"id":"SET-024-choice-6b9d975f","label":"B","text":"{1, 4, 5, 6, 7}"},{"id":"SET-024-choice-0005a57d","label":"C","text":"{1, 3, 5, 7}"},{"id":"SET-024-choice-9d29f672","label":"D","text":"{1, 5, 7}"}],"correctChoiceId":"SET-024-choice-9d29f672","hint":"Remove the intersection A ∩ B before restricting to C.","explanation":"A ∩ B={2,3}. Its complement is {1,4,5,6,7}; intersecting with C gives {1,5,7}."},{"id":"SET-025","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2025,"difficulty":"Medium","curriculumStandards":["4.3.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7,8}, A={1,2,3} and B={3,4,5}. Complements are taken in U. Find A′ ∩ B′.","choices":[{"id":"SET-025-choice-da75b8d3","label":"A","text":"{1, 2, 3, 4, 5}"},{"id":"SET-025-choice-b2a7d24d","label":"B","text":"{1, 2, 4, 5, 6, 7, 8}"},{"id":"SET-025-choice-c7401b91","label":"C","text":"{3}"},{"id":"SET-025-choice-1b95eb3e","label":"D","text":"{6, 7, 8}"}],"correctChoiceId":"SET-025-choice-1b95eb3e","hint":"The elements must be outside both A and B.","explanation":"A′ ∩ B′=(A ∪ B)′. Removing {1,2,3,4,5} from U leaves {6,7,8}."},{"id":"SET-026","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2026,"difficulty":"Medium","curriculumStandards":["4.3.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6}, A={1,2,3} and B={2,3,4}. Complements are taken in U. Find A′ ∪ B′.","choices":[{"id":"SET-026-choice-c5a73863","label":"A","text":"{2, 3}"},{"id":"SET-026-choice-2e38cc51","label":"B","text":"{5, 6}"},{"id":"SET-026-choice-42854fb4","label":"C","text":"{1, 2, 3, 4}"},{"id":"SET-026-choice-8545950b","label":"D","text":"{1, 4, 5, 6}"}],"correctChoiceId":"SET-026-choice-8545950b","hint":"Use De Morgan’s law or list the two complements.","explanation":"A′={4,5,6} and B′={1,5,6}. Their union is {1,4,5,6}, equal to (A ∩ B)′."},{"id":"SET-027","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2027,"difficulty":"Hard","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"For all sets A, B and C in the same universe, which expression is always equal to A ∩ (B ∪ C)?","choices":[{"id":"SET-027-choice-97773376","label":"A","text":"(A ∩ B) ∩ C"},{"id":"SET-027-choice-069d8128","label":"B","text":"A ∪ (B ∩ C)"},{"id":"SET-027-choice-85a56e1c","label":"C","text":"(A ∩ B) ∪ (A ∩ C)"},{"id":"SET-027-choice-859e2c30","label":"D","text":"(A ∪ B) ∩ C"}],"correctChoiceId":"SET-027-choice-85a56e1c","hint":"Check membership using AND and OR.","explanation":"Membership requires A and at least one of B or C. This is exactly (A ∩ B) ∪ (A ∩ C)."},{"id":"SET-028","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2028,"difficulty":"Medium","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A is the set of Fire cards and B is the set of cards costing 2 Energy. Complements are taken in the teaching pool of cards. Which expression selects Fire cards that do NOT cost 2 Energy?","choices":[{"id":"SET-028-choice-213000fe","label":"A","text":"(A ∪ B)′"},{"id":"SET-028-choice-e79ddced","label":"B","text":"A ∪ B′"},{"id":"SET-028-choice-3100ccf6","label":"C","text":"A ∩ B′"},{"id":"SET-028-choice-d6160f96","label":"D","text":"A′ ∩ B"}],"correctChoiceId":"SET-028-choice-3100ccf6","hint":"The card must be in A and outside B.","explanation":"The required condition is Fire AND not cost-2, represented by A ∩ B′."},{"id":"SET-029","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2029,"difficulty":"Hard","curriculumStandards":["4.3.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6}, A={1,2,3} and B={2,4,6}. Complements are taken in U. Find (A ∪ B′)′.","choices":[{"id":"SET-029-choice-13ccb4bc","label":"A","text":"{4, 6}"},{"id":"SET-029-choice-f5e1420e","label":"B","text":"{2}"},{"id":"SET-029-choice-c6207456","label":"C","text":"{1, 2, 3, 5}"},{"id":"SET-029-choice-6000be55","label":"D","text":"{1, 3, 5}"}],"correctChoiceId":"SET-029-choice-13ccb4bc","hint":"Use (A ∪ B′)′=A′ ∩ B.","explanation":"B′={1,3,5}; A ∪ B′={1,2,3,5}. Its complement is {4,6}."},{"id":"SET-030","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2030,"difficulty":"Hard","curriculumStandards":["4.3.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7,8}, A={1,2,3,4}, B={2,3,5} and C={3,6}. Complements are taken in U. Find (A ∩ B ∩ C)′.","choices":[{"id":"SET-030-choice-1614c589","label":"A","text":"{7, 8}"},{"id":"SET-030-choice-b2a7d24d","label":"B","text":"{1, 2, 4, 5, 6, 7, 8}"},{"id":"SET-030-choice-c5a73863","label":"C","text":"{2, 3}"},{"id":"SET-030-choice-c7401b91","label":"D","text":"{3}"}],"correctChoiceId":"SET-030-choice-b2a7d24d","hint":"Find the element shared by all three sets first.","explanation":"The triple intersection is {3}. Its complement contains every element of U except 3."},{"id":"SET-031","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2031,"difficulty":"Hard","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7,8}, A={1,2,3,4}, B={3,4,5} and C={4,6}. Complements are taken in U. Find (A ∩ B) ∪ C′.","choices":[{"id":"SET-031-choice-4e24a127","label":"A","text":"{3, 4, 6}"},{"id":"SET-031-choice-7112258f","label":"B","text":"{1, 2, 3, 5, 7, 8}"},{"id":"SET-031-choice-c7401b91","label":"C","text":"{3}"},{"id":"SET-031-choice-f2cf6509","label":"D","text":"{1, 2, 3, 4, 5, 7, 8}"}],"correctChoiceId":"SET-031-choice-f2cf6509","hint":"Find C′ independently, then add the intersection.","explanation":"A ∩ B={3,4} and C′={1,2,3,5,7,8}. Their union also includes 4."},{"id":"SET-032","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2032,"difficulty":"Hard","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7}, A={1,2,3}, B={2,3,4} and C={3,4,5}. Complements are taken in U. Find A′ ∪ (B ∩ C).","choices":[{"id":"SET-032-choice-79bc9b35","label":"A","text":"{4}"},{"id":"SET-032-choice-9a83d2c3","label":"B","text":"{2, 3, 4, 5, 6, 7}"},{"id":"SET-032-choice-5f52c17a","label":"C","text":"{4, 5, 6, 7}"},{"id":"SET-032-choice-6eb7e24d","label":"D","text":"{3, 4, 5, 6, 7}"}],"correctChoiceId":"SET-032-choice-6eb7e24d","hint":"Take the complement of A and the intersection B ∩ C, then unite them.","explanation":"A′={4,5,6,7} and B ∩ C={3,4}. The union is {3,4,5,6,7}."},{"id":"SET-033","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2033,"difficulty":"Medium","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A guild has 40 members. 24 own a sword, 19 own a shield and 11 own both. How many own a sword but no shield?","choices":[{"id":"SET-033-choice-3fdba35f","label":"A","text":"13"},{"id":"SET-033-choice-2c624232","label":"B","text":"8"},{"id":"SET-033-choice-e29c9c18","label":"C","text":"32"},{"id":"SET-033-choice-4fc82b26","label":"D","text":"11"}],"correctChoiceId":"SET-033-choice-3fdba35f","hint":"Remove the overlap from the sword count.","explanation":"Sword only = 24−11=13 members."},{"id":"SET-034","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2034,"difficulty":"Hard","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A group is divided into disjoint regions by ownership of a map M, lantern L and key K. Exactly M and L only: 4 people; exactly M and K only: 3; exactly L and K only: 5; all three: 2. How many own at least two of these items?","choices":[{"id":"SET-034-choice-b17ef6d1","label":"A","text":"16"},{"id":"SET-034-choice-4ec9599f","label":"B","text":"18"},{"id":"SET-034-choice-8527a891","label":"C","text":"14"},{"id":"SET-034-choice-6b51d431","label":"D","text":"12"}],"correctChoiceId":"SET-034-choice-8527a891","hint":"The stated regions do not overlap. Include the all-three region once.","explanation":"At least two includes the three exactly-two regions and the all-three region: 4+3+5+2=14."},{"id":"SET-035","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2035,"difficulty":"Hard","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A guild has 50 members. 28 own a map, 25 own a lantern and 12 own both. How many own exactly one of these two items?","choices":[{"id":"SET-035-choice-35135aaa","label":"A","text":"29"},{"id":"SET-035-choice-6b51d431","label":"B","text":"12"},{"id":"SET-035-choice-3d914f93","label":"C","text":"41"},{"id":"SET-035-choice-4523540f","label":"D","text":"17"}],"correctChoiceId":"SET-035-choice-35135aaa","hint":"Add map-only and lantern-only.","explanation":"Map-only=28−12=16; lantern-only=25−12=13. Exactly one=16+13=29."},{"id":"SET-036","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2036,"difficulty":"Medium","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A teaching pool contains 18 distinct cards. 10 are Fire, 9 cost 2 Energy, and 4 are both Fire and cost-2. How many are neither Fire nor cost-2?","choices":[{"id":"SET-036-choice-ef2d127d","label":"A","text":"5"},{"id":"SET-036-choice-e629fa65","label":"B","text":"15"},{"id":"SET-036-choice-4b227777","label":"C","text":"4"},{"id":"SET-036-choice-4e074085","label":"D","text":"3"}],"correctChoiceId":"SET-036-choice-4e074085","hint":"Count the union and subtract from the pool size.","explanation":"The union contains 10+9−4=15 cards. The complement has 18−15=3 cards."},{"id":"SET-037","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2037,"difficulty":"Hard","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6,7,8}, A∪B={1,2,3,4,5,6}, A∩B={3,4}, and A={1,2,3,4}. Find B.","choices":[{"id":"SET-037-choice-224d736d","label":"A","text":"{1, 2, 3, 4, 5, 6}"},{"id":"SET-037-choice-129d9821","label":"B","text":"{1, 2, 5, 6}"},{"id":"SET-037-choice-2e38cc51","label":"C","text":"{5, 6}"},{"id":"SET-037-choice-a5a976d6","label":"D","text":"{3, 4, 5, 6}"}],"correctChoiceId":"SET-037-choice-a5a976d6","hint":"B must contain the intersection and the union elements outside A.","explanation":"B contains shared elements {3,4} and B-only elements {5,6}. It cannot include 1 or 2 because that would enlarge the intersection."},{"id":"SET-038","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2038,"difficulty":"Hard","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A guild has 60 members. For map M, lantern L and key K, n(M)=30, n(L)=25, n(K)=20, n(M∩L)=10, n(M∩K)=8, n(L∩K)=7 and n(M∩L∩K)=4. The pairwise counts include the all-three members. How many own none of the three items?","choices":[{"id":"SET-038-choice-4a44dc15","label":"A","text":"10"},{"id":"SET-038-choice-e7f6c011","label":"B","text":"6"},{"id":"SET-038-choice-2fca346d","label":"C","text":"54"},{"id":"SET-038-choice-8527a891","label":"D","text":"14"}],"correctChoiceId":"SET-038-choice-e7f6c011","hint":"Use inclusion-exclusion; add the triple intersection back once.","explanation":"The union has 30+25+20−10−8−7+4=54 members. None: 60−54=6."},{"id":"SET-039","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2039,"difficulty":"Hard","curriculumStandards":["4.3.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"U={1,2,3,4,5,6}, A={1,2,3}, B={3,4,5} and C={2,3,5}. Complements are taken in U. Find (A ∪ B) ∩ C′.","choices":[{"id":"SET-039-choice-9092fd2d","label":"A","text":"{1, 4, 6}"},{"id":"SET-039-choice-8d521197","label":"B","text":"{1, 4}"},{"id":"SET-039-choice-da75b8d3","label":"C","text":"{1, 2, 3, 4, 5}"},{"id":"SET-039-choice-fb0f135f","label":"D","text":"{2, 3, 5}"}],"correctChoiceId":"SET-039-choice-8d521197","hint":"Keep union elements that lie outside C.","explanation":"A ∪ B={1,2,3,4,5}; C′={1,4,6}. Their intersection is {1,4}."},{"id":"SET-040","topicId":"T2","topicCode":"SET","chapter":4,"topic":"Operations on Sets","seed":2040,"difficulty":"Medium","curriculumStandards":["4.3.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A teaching pool has unique card IDs U={a,b,c,d,e,f,g,h}. Fire F={a,c,e,g}; cost-2 E={b,c,f,g}; upgraded G={c,d,g,h}. Find n((F ∩ E) ∩ G′), where complement is in U.","choices":[{"id":"SET-040-choice-5feceb66","label":"A","text":"0"},{"id":"SET-040-choice-6b86b273","label":"B","text":"1"},{"id":"SET-040-choice-4b227777","label":"C","text":"4"},{"id":"SET-040-choice-d4735e3a","label":"D","text":"2"}],"correctChoiceId":"SET-040-choice-5feceb66","hint":"Check whether any Fire cost-2 card is not upgraded.","explanation":"F ∩ E={c,g}. Both are upgraded, so neither belongs to G′. The required set is empty and its count is 0."},{"id":"LOGIC-001","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3001,"difficulty":"Easy","curriculumStandards":["3.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A statement is a sentence that has a definite truth value. Which option is a statement?","choices":[{"id":"LOGIC-001-choice-1a27d419","label":"A","text":"10 is an even number."},{"id":"LOGIC-001-choice-73d0b678","label":"B","text":"x + 2 = 5, with no value or quantifier given for x."},{"id":"LOGIC-001-choice-1b90ff73","label":"C","text":"How many cards are there?"},{"id":"LOGIC-001-choice-f5598eeb","label":"D","text":"Open the gate!"}],"correctChoiceId":"LOGIC-001-choice-1a27d419","hint":"A command, a question and an unquantified open sentence have no fixed truth value.","explanation":"“10 is an even number” can be judged true. The other options are not statements in the stated form."},{"id":"LOGIC-002","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3002,"difficulty":"Easy","curriculumStandards":["3.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Which option is NOT a mathematical statement?","choices":[{"id":"LOGIC-002-choice-c3510c4f","label":"A","text":"7 is a prime number."},{"id":"LOGIC-002-choice-8b907976","label":"B","text":"Is 7 a prime number?"},{"id":"LOGIC-002-choice-b57ae2f8","label":"C","text":"Every multiple of 4 is even."},{"id":"LOGIC-002-choice-d9fc6f56","label":"D","text":"9 is an even number."}],"correctChoiceId":"LOGIC-002-choice-8b907976","hint":"A false declarative sentence can still be a statement.","explanation":"“Is 7 a prime number?” asks a question. The other sentences have definite truth values, even when false."},{"id":"LOGIC-003","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3003,"difficulty":"Easy","curriculumStandards":["3.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p: “6² = 36.” q: “15 is a prime number.” Give the truth values of p and q, in that order.","choices":[{"id":"LOGIC-003-choice-99429df6","label":"A","text":"True, True"},{"id":"LOGIC-003-choice-8bd3f6a8","label":"B","text":"False, True"},{"id":"LOGIC-003-choice-8c19106e","label":"C","text":"True, False"},{"id":"LOGIC-003-choice-fe1001a4","label":"D","text":"False, False"}],"correctChoiceId":"LOGIC-003-choice-8c19106e","hint":"Check the square and whether 15 has factors other than 1 and itself.","explanation":"6²=36 is true. Since 15=3×5, 15 is not prime, so q is false."},{"id":"LOGIC-004","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3004,"difficulty":"Easy","curriculumStandards":["3.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"The domain is D={2,4,6,8}. p: “All elements of D are even.” q: “Some elements of D are odd.” Here “some” means at least one. Give the truth values of p and q.","choices":[{"id":"LOGIC-004-choice-99429df6","label":"A","text":"True, True"},{"id":"LOGIC-004-choice-8c19106e","label":"B","text":"True, False"},{"id":"LOGIC-004-choice-8bd3f6a8","label":"C","text":"False, True"},{"id":"LOGIC-004-choice-fe1001a4","label":"D","text":"False, False"}],"correctChoiceId":"LOGIC-004-choice-8c19106e","hint":"All requires every element; some requires at least one.","explanation":"Every listed element is even, and none is odd. Thus p is true and q is false."},{"id":"LOGIC-005","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3005,"difficulty":"Easy","curriculumStandards":["3.1.1","3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p: “All prime numbers are odd.” q: “Some prime numbers are even.” Give the truth values of p and q.","choices":[{"id":"LOGIC-005-choice-8c19106e","label":"A","text":"True, False"},{"id":"LOGIC-005-choice-8bd3f6a8","label":"B","text":"False, True"},{"id":"LOGIC-005-choice-99429df6","label":"C","text":"True, True"},{"id":"LOGIC-005-choice-fe1001a4","label":"D","text":"False, False"}],"correctChoiceId":"LOGIC-005-choice-8bd3f6a8","hint":"Check whether an even prime number exists.","explanation":"2 is prime and even. It is a counterexample to p and an example proving q."},{"id":"LOGIC-006","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3006,"difficulty":"Easy","curriculumStandards":["3.1.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"A teaching pool contains exactly three cards: c1 is blue and costs 0; c2 is red and costs 1; c3 is blue and costs 2. Which statement is true?","choices":[{"id":"LOGIC-006-choice-3eab320c","label":"A","text":"All cards are blue."},{"id":"LOGIC-006-choice-6ad57d96","label":"B","text":"No blue card costs 0."},{"id":"LOGIC-006-choice-38f0cae1","label":"C","text":"Some blue cards cost 0."},{"id":"LOGIC-006-choice-3025ecc4","label":"D","text":"All blue cards cost 0."}],"correctChoiceId":"LOGIC-006-choice-38f0cae1","hint":"Use c1 and c3 to test the claims about blue cards.","explanation":"c1 proves that at least one blue card costs 0. c3 shows that not all blue cards cost 0."},{"id":"LOGIC-007","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3007,"difficulty":"Medium","curriculumStandards":["3.1.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"What is the negation of “All Fire cards are Attack cards”?","choices":[{"id":"LOGIC-007-choice-1b492b34","label":"A","text":"At least one Fire card is not an Attack card."},{"id":"LOGIC-007-choice-25b1ed74","label":"B","text":"At least one Fire card is an Attack card."},{"id":"LOGIC-007-choice-f7733862","label":"C","text":"No Fire card is an Attack card."},{"id":"LOGIC-007-choice-e0455cd6","label":"D","text":"All Attack cards are Fire cards."}],"correctChoiceId":"LOGIC-007-choice-1b492b34","hint":"To deny “all”, one counterexample is enough.","explanation":"The original fails when there is a Fire card outside Attack. Negation does not require every Fire card to be outside Attack."},{"id":"LOGIC-008","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3008,"difficulty":"Medium","curriculumStandards":["3.1.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"What is the negation of “Some blue cards cost 0 Energy”? Here “some” means at least one.","choices":[{"id":"LOGIC-008-choice-9a3835f1","label":"A","text":"Some blue cards do not cost 0 Energy."},{"id":"LOGIC-008-choice-860d8382","label":"B","text":"All blue cards cost 0 Energy."},{"id":"LOGIC-008-choice-cc9feb7f","label":"C","text":"No blue card costs 0 Energy."},{"id":"LOGIC-008-choice-3eab320c","label":"D","text":"All cards are blue."}],"correctChoiceId":"LOGIC-008-choice-cc9feb7f","hint":"Negate the existence of even one matching card.","explanation":"The negation says that there is no card that is both blue and cost-0."},{"id":"LOGIC-009","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3009,"difficulty":"Easy","curriculumStandards":["3.1.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Let E be the player’s current Energy, a nonnegative integer. What is the negation of “E ≥ 2”?","choices":[{"id":"LOGIC-009-choice-3fc8e9f0","label":"A","text":"E > 2"},{"id":"LOGIC-009-choice-1c443844","label":"B","text":"E = 2"},{"id":"LOGIC-009-choice-efc75829","label":"C","text":"E ≤ 2"},{"id":"LOGIC-009-choice-7a33fc80","label":"D","text":"E < 2"}],"correctChoiceId":"LOGIC-009-choice-7a33fc80","hint":"The negation must cover exactly the values excluded by the original.","explanation":"Values below 2 make E≥2 false. At E=2, the original is true, so E≤2 is not its negation."},{"id":"LOGIC-010","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3010,"difficulty":"Medium","curriculumStandards":["3.1.2","3.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p: “The gate is open.” q: “The lamp is lit.” What is the negation of “p AND q”? OR is inclusive.","choices":[{"id":"LOGIC-010-choice-bd7078ab","label":"A","text":"p OR q"},{"id":"LOGIC-010-choice-d85585b7","label":"B","text":"(NOT p) OR (NOT q)"},{"id":"LOGIC-010-choice-60f90608","label":"C","text":"p AND (NOT q)"},{"id":"LOGIC-010-choice-f9d299a2","label":"D","text":"(NOT p) AND (NOT q)"}],"correctChoiceId":"LOGIC-010-choice-d85585b7","hint":"An AND statement fails if at least one part fails.","explanation":"By De Morgan’s law, NOT(p AND q) is (NOT p) OR (NOT q). Both parts need not be false."},{"id":"LOGIC-011","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3011,"difficulty":"Easy","curriculumStandards":["3.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p is true and q is false. Which compound statement is false? OR is inclusive.","choices":[{"id":"LOGIC-011-choice-d85585b7","label":"A","text":"(NOT p) OR (NOT q)"},{"id":"LOGIC-011-choice-cc64e728","label":"B","text":"NOT q"},{"id":"LOGIC-011-choice-bd7078ab","label":"C","text":"p OR q"},{"id":"LOGIC-011-choice-32841c91","label":"D","text":"p AND q"}],"correctChoiceId":"LOGIC-011-choice-32841c91","hint":"AND requires both parts to be true.","explanation":"p AND q is false because q is false. Each other option evaluates to true."},{"id":"LOGIC-012","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3012,"difficulty":"Easy","curriculumStandards":["3.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p and q are both true. What is the truth value of “p OR q” when OR is inclusive?","choices":[{"id":"LOGIC-012-choice-ced10964","label":"A","text":"It has no truth value when both parts are true."},{"id":"LOGIC-012-choice-ec888f51","label":"B","text":"True, because at least one part is true, including when both are true."},{"id":"LOGIC-012-choice-68e7c243","label":"C","text":"False, because exactly one part must be true."},{"id":"LOGIC-012-choice-1a59388f","label":"D","text":"False, because both parts are true."}],"correctChoiceId":"LOGIC-012-choice-ec888f51","hint":"Inclusive OR permits both events or statements.","explanation":"Inclusive OR is true when p is true, q is true, or both are true."},{"id":"LOGIC-013","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3013,"difficulty":"Easy","curriculumStandards":["3.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p is false and q is true. Give the truth values of “p AND q” and “p OR q”, in that order. OR is inclusive.","choices":[{"id":"LOGIC-013-choice-8bd3f6a8","label":"A","text":"False, True"},{"id":"LOGIC-013-choice-8c19106e","label":"B","text":"True, False"},{"id":"LOGIC-013-choice-fe1001a4","label":"C","text":"False, False"},{"id":"LOGIC-013-choice-99429df6","label":"D","text":"True, True"}],"correctChoiceId":"LOGIC-013-choice-8bd3f6a8","hint":"Evaluate the two operations separately.","explanation":"AND is false because p is false. OR is true because q is true."},{"id":"LOGIC-014","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3014,"difficulty":"Medium","curriculumStandards":["3.1.4"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p is true and q is false. Give the truth values of “if p then q” and “if q then p”, in that order.","choices":[{"id":"LOGIC-014-choice-fe1001a4","label":"A","text":"False, False"},{"id":"LOGIC-014-choice-8c19106e","label":"B","text":"True, False"},{"id":"LOGIC-014-choice-99429df6","label":"C","text":"True, True"},{"id":"LOGIC-014-choice-8bd3f6a8","label":"D","text":"False, True"}],"correctChoiceId":"LOGIC-014-choice-8bd3f6a8","hint":"An implication is false only when its premise is true and its conclusion is false.","explanation":"p→q is true→false, so it is false. q→p has a false premise, so it is true."},{"id":"LOGIC-015","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3015,"difficulty":"Easy","curriculumStandards":["3.1.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p: “12 is a multiple of 3.” q: “12 is odd.” Give the truth values of “p AND q” and “p OR q”, in that order. OR is inclusive.","choices":[{"id":"LOGIC-015-choice-99429df6","label":"A","text":"True, True"},{"id":"LOGIC-015-choice-8bd3f6a8","label":"B","text":"False, True"},{"id":"LOGIC-015-choice-fe1001a4","label":"C","text":"False, False"},{"id":"LOGIC-015-choice-8c19106e","label":"D","text":"True, False"}],"correctChoiceId":"LOGIC-015-choice-8bd3f6a8","hint":"Decide p and q before combining them.","explanation":"p is true and q is false. Their AND is false; their inclusive OR is true."},{"id":"LOGIC-016","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3016,"difficulty":"Medium","curriculumStandards":["3.1.4"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Which truth-value pair makes the implication “if p then q” false?","choices":[{"id":"LOGIC-016-choice-f713b091","label":"A","text":"p=False, q=True"},{"id":"LOGIC-016-choice-95dbbd34","label":"B","text":"p=True, q=False"},{"id":"LOGIC-016-choice-220ec202","label":"C","text":"p=False, q=False"},{"id":"LOGIC-016-choice-37ea5877","label":"D","text":"p=True, q=True"}],"correctChoiceId":"LOGIC-016-choice-95dbbd34","hint":"Look for a fulfilled premise followed by a failed conclusion.","explanation":"An implication fails only in the true-premise, false-conclusion case."},{"id":"LOGIC-017","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3017,"difficulty":"Easy","curriculumStandards":["3.1.4"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"p: “A rune glows.” q: “The gate opens.” Which sentence represents “if p then q”?","choices":[{"id":"LOGIC-017-choice-1d51af9a","label":"A","text":"If a rune glows, then the gate opens."},{"id":"LOGIC-017-choice-792fc40a","label":"B","text":"A rune glows if and only if the gate opens."},{"id":"LOGIC-017-choice-295f7675","label":"C","text":"If a rune does not glow, then the gate does not open."},{"id":"LOGIC-017-choice-5b7cde4b","label":"D","text":"If the gate opens, then a rune glows."}],"correctChoiceId":"LOGIC-017-choice-1d51af9a","hint":"Keep p as the premise and q as the conclusion.","explanation":"p→q places the glowing rune first as the condition and the opening gate as the conclusion."},{"id":"LOGIC-018","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3018,"difficulty":"Medium","curriculumStandards":["3.1.4"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Which pair of implications is equivalent to “The gate opens if and only if a key is present”?","choices":[{"id":"LOGIC-018-choice-16eea4fc","label":"A","text":"If the gate opens then a key is present; no reverse implication is needed."},{"id":"LOGIC-018-choice-9a3e4aab","label":"B","text":"If the gate opens then no key is present; AND if no key is present then the gate opens."},{"id":"LOGIC-018-choice-9894e4ed","label":"C","text":"If the gate opens then a key is present; AND if a key is present then the gate opens."},{"id":"LOGIC-018-choice-1a4ad3d6","label":"D","text":"If a key is present then the gate opens; no reverse implication is needed."}],"correctChoiceId":"LOGIC-018-choice-9894e4ed","hint":"A biconditional requires both directions.","explanation":"“p if and only if q” means (p→q) AND (q→p). One direction alone is not sufficient."},{"id":"LOGIC-019","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3019,"difficulty":"Easy","curriculumStandards":["3.1.5"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Original implication: “If a number is divisible by 4, then it is even.” Which is its converse?","choices":[{"id":"LOGIC-019-choice-0dbff379","label":"A","text":"If a number is not even, then it is not divisible by 4."},{"id":"LOGIC-019-choice-9bc2dca7","label":"B","text":"If a number is even, then it is divisible by 4."},{"id":"LOGIC-019-choice-42fa00e1","label":"C","text":"If a number is divisible by 4, then it is even."},{"id":"LOGIC-019-choice-7849fd89","label":"D","text":"If a number is not divisible by 4, then it is not even."}],"correctChoiceId":"LOGIC-019-choice-9bc2dca7","hint":"The converse swaps the premise and conclusion.","explanation":"The converse of p→q is q→p. Its truth value need not match the original."},{"id":"LOGIC-020","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3020,"difficulty":"Easy","curriculumStandards":["3.1.5"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Original implication: “If a rune is Fire, then it is red.” Which is its inverse?","choices":[{"id":"LOGIC-020-choice-f67938e5","label":"A","text":"If a rune is not red, then it is not Fire."},{"id":"LOGIC-020-choice-4cef7dad","label":"B","text":"A rune is Fire if and only if it is red."},{"id":"LOGIC-020-choice-391ab21e","label":"C","text":"If a rune is red, then it is Fire."},{"id":"LOGIC-020-choice-010bae33","label":"D","text":"If a rune is not Fire, then it is not red."}],"correctChoiceId":"LOGIC-020-choice-010bae33","hint":"Negate both parts while keeping their order.","explanation":"The inverse of p→q is (NOT p)→(NOT q). It is not necessarily equivalent to the original."},{"id":"LOGIC-021","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3021,"difficulty":"Easy","curriculumStandards":["3.1.5"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Original implication: “If a card is a Guard card, then it is blue.” Which is its contrapositive?","choices":[{"id":"LOGIC-021-choice-0f57a882","label":"A","text":"If a card is not a Guard card, then it is not blue."},{"id":"LOGIC-021-choice-1851f3c1","label":"B","text":"If a card is blue, then it is a Guard card."},{"id":"LOGIC-021-choice-ab3ab73e","label":"C","text":"If a card is a Guard card, then it is not blue."},{"id":"LOGIC-021-choice-db848a3b","label":"D","text":"If a card is not blue, then it is not a Guard card."}],"correctChoiceId":"LOGIC-021-choice-db848a3b","hint":"Swap the two parts and negate both.","explanation":"The contrapositive of p→q is (NOT q)→(NOT p). It is logically equivalent to the original."},{"id":"LOGIC-022","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3022,"difficulty":"Medium","curriculumStandards":["3.1.5","3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"For all integers n, p: “If n is divisible by 4, then n is even.” q is the converse of p. Give the truth values of p and q.","choices":[{"id":"LOGIC-022-choice-8c19106e","label":"A","text":"True, False"},{"id":"LOGIC-022-choice-fe1001a4","label":"B","text":"False, False"},{"id":"LOGIC-022-choice-99429df6","label":"C","text":"True, True"},{"id":"LOGIC-022-choice-8bd3f6a8","label":"D","text":"False, True"}],"correctChoiceId":"LOGIC-022-choice-8c19106e","hint":"Use divisibility for p, then test whether every even number is divisible by 4.","explanation":"If n=4k, then n=2(2k), so p is true. The converse is false because 2 is even but not divisible by 4."},{"id":"LOGIC-023","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3023,"difficulty":"Medium","curriculumStandards":["3.1.5"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Which implication is always logically equivalent to “if p then q”?","choices":[{"id":"LOGIC-023-choice-7f823ade","label":"A","text":"If p, then NOT q."},{"id":"LOGIC-023-choice-16e02a5c","label":"B","text":"If NOT q, then NOT p."},{"id":"LOGIC-023-choice-69f64f3b","label":"C","text":"If NOT p, then NOT q."},{"id":"LOGIC-023-choice-1f5f5e9a","label":"D","text":"If q, then p."}],"correctChoiceId":"LOGIC-023-choice-16e02a5c","hint":"Only the contrapositive preserves every truth-table result.","explanation":"p→q and (NOT q)→(NOT p) have identical truth values for every assignment of p and q."},{"id":"LOGIC-024","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3024,"difficulty":"Easy","curriculumStandards":["3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Which number is a counterexample to “All prime numbers are odd”?","choices":[{"id":"LOGIC-024-choice-d4735e3a","label":"A","text":"2"},{"id":"LOGIC-024-choice-4e074085","label":"B","text":"3"},{"id":"LOGIC-024-choice-19581e27","label":"C","text":"9"},{"id":"LOGIC-024-choice-ef2d127d","label":"D","text":"5"}],"correctChoiceId":"LOGIC-024-choice-d4735e3a","hint":"A counterexample must be prime and not odd.","explanation":"2 is prime and even. 3 and 5 are odd primes; 9 is not prime and cannot refute the claim."},{"id":"LOGIC-025","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3025,"difficulty":"Medium","curriculumStandards":["3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"The domain is the positive integers. Which number is a counterexample to “n² > n for every n”?","choices":[{"id":"LOGIC-025-choice-6b86b273","label":"A","text":"1"},{"id":"LOGIC-025-choice-4b227777","label":"B","text":"4"},{"id":"LOGIC-025-choice-d4735e3a","label":"C","text":"2"},{"id":"LOGIC-025-choice-4e074085","label":"D","text":"3"}],"correctChoiceId":"LOGIC-025-choice-6b86b273","hint":"Look for a permitted value where the strict inequality fails.","explanation":"At n=1, n²=1, so n² is equal to n rather than greater. 0 is not in the stated domain."},{"id":"LOGIC-026","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3026,"difficulty":"Medium","curriculumStandards":["3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"The domain is the integers. Which value is a counterexample to “If n² > 9, then n > 3”?","choices":[{"id":"LOGIC-026-choice-4b227777","label":"A","text":"4"},{"id":"LOGIC-026-choice-4e074085","label":"B","text":"3"},{"id":"LOGIC-026-choice-a6dd6f11","label":"C","text":"−4"},{"id":"LOGIC-026-choice-d4735e3a","label":"D","text":"2"}],"correctChoiceId":"LOGIC-026-choice-a6dd6f11","hint":"The premise must be true while the conclusion is false.","explanation":"At n=−4, n²=16>9 but n>3 is false. Thus the implication fails."},{"id":"LOGIC-027","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3027,"difficulty":"Medium","curriculumStandards":["3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Which value is a counterexample to “If n is even, then n is a multiple of 4”, for integers n?","choices":[{"id":"LOGIC-027-choice-2c624232","label":"A","text":"8"},{"id":"LOGIC-027-choice-4e074085","label":"B","text":"3"},{"id":"LOGIC-027-choice-4b227777","label":"C","text":"4"},{"id":"LOGIC-027-choice-e7f6c011","label":"D","text":"6"}],"correctChoiceId":"LOGIC-027-choice-e7f6c011","hint":"Find an even number that is not divisible by 4.","explanation":"6 is even, but 6 is not a multiple of 4. An odd number does not satisfy the premise."},{"id":"LOGIC-028","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3028,"difficulty":"Medium","curriculumStandards":["3.1.4","3.1.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"For integers n, is “n is divisible by 4 if and only if n is even” true?","choices":[{"id":"LOGIC-028-choice-bb6487b4","label":"A","text":"False: n=2 is even but is not divisible by 4."},{"id":"LOGIC-028-choice-bcd1557e","label":"B","text":"True: being divisible by 4 always makes n even."},{"id":"LOGIC-028-choice-f375b732","label":"C","text":"True: one direction is enough for “if and only if”."},{"id":"LOGIC-028-choice-d4ac441b","label":"D","text":"False: n=4 is not even."}],"correctChoiceId":"LOGIC-028-choice-bb6487b4","hint":"A biconditional needs the reverse implication as well.","explanation":"The forward direction is true, but the reverse fails at n=2. Both directions are needed, so the biconditional is false."},{"id":"LOGIC-029","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3029,"difficulty":"Easy","curriculumStandards":["3.2.1","3.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Assume both premises are true: (1) Every marked rune opens Gate A. (2) Rune R is marked. Which conclusion follows deductively?","choices":[{"id":"LOGIC-029-choice-7bf6705c","label":"A","text":"Rune R does not open Gate A."},{"id":"LOGIC-029-choice-ab91ca1e","label":"B","text":"Every rune that opens Gate A is marked."},{"id":"LOGIC-029-choice-ebea3dd9","label":"C","text":"Rune R opens Gate A."},{"id":"LOGIC-029-choice-4f0a5b1f","label":"D","text":"No unmarked rune opens Gate A."}],"correctChoiceId":"LOGIC-029-choice-ebea3dd9","hint":"Apply the general rule to the named rune.","explanation":"This is modus ponens: marked→opens; marked; therefore opens. The premises do not exclude other ways to open the gate."},{"id":"LOGIC-030","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3030,"difficulty":"Medium","curriculumStandards":["3.2.2","3.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Assume both premises are true: (1) If a key is present, the gate opens. (2) The gate does not open. Which conclusion follows?","choices":[{"id":"LOGIC-030-choice-a75df855","label":"A","text":"No key is present."},{"id":"LOGIC-030-choice-43051470","label":"B","text":"Every open gate has a key."},{"id":"LOGIC-030-choice-2a301843","label":"C","text":"A key is present."},{"id":"LOGIC-030-choice-abcacc8c","label":"D","text":"The gate opens."}],"correctChoiceId":"LOGIC-030-choice-a75df855","hint":"Use modus tollens.","explanation":"From p→q and NOT q, conclude NOT p. A present key would force the gate to open, contradicting premise 2."},{"id":"LOGIC-031","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3031,"difficulty":"Hard","curriculumStandards":["3.2.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Argument: “If a card is Fire, then it is Attack. Card c7 is Attack. Therefore c7 is Fire.” Is this deduction valid based only on these premises?","choices":[{"id":"LOGIC-031-choice-cc418e38","label":"A","text":"Valid: every Attack card must be Fire."},{"id":"LOGIC-031-choice-e6999344","label":"B","text":"Invalid: no Fire card can be Attack."},{"id":"LOGIC-031-choice-88838e68","label":"C","text":"Valid: the conclusion repeats a word from each premise."},{"id":"LOGIC-031-choice-4bd71669","label":"D","text":"Invalid: c7 could be an Attack card that is not Fire."}],"correctChoiceId":"LOGIC-031-choice-4bd71669","hint":"Test whether both premises can be true while the conclusion is false.","explanation":"Let Fire=false and Attack=true for c7. Both premises are true, but the conclusion is false. This is affirming the consequent."},{"id":"LOGIC-032","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3032,"difficulty":"Hard","curriculumStandards":["3.2.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Argument: “If a rune is Fire, then it glows. Rune R is not Fire. Therefore R does not glow.” Is this deduction valid based only on these premises?","choices":[{"id":"LOGIC-032-choice-7fcf3355","label":"A","text":"Valid: removing the cause always removes the effect."},{"id":"LOGIC-032-choice-a1f63ae5","label":"B","text":"Valid: the inverse is always equivalent to the original."},{"id":"LOGIC-032-choice-9bb0ff9b","label":"C","text":"Invalid: Fire runes never glow."},{"id":"LOGIC-032-choice-a79cd5e3","label":"D","text":"Invalid: a non-Fire rune might still glow."}],"correctChoiceId":"LOGIC-032-choice-a79cd5e3","hint":"The rule gives one sufficient condition, not the only possible condition.","explanation":"Fire=false and glows=true makes both premises true but the conclusion false. This is denying the antecedent."},{"id":"LOGIC-033","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3033,"difficulty":"Hard","curriculumStandards":["3.2.2"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Argument over integers: “All odd integers are divisible by 4. 3 is odd. Therefore 3 is divisible by 4.” Which assessment is correct? Sound means valid with all premises true.","choices":[{"id":"LOGIC-033-choice-782ccc4a","label":"A","text":"Invalid because every false conclusion makes the argument form invalid."},{"id":"LOGIC-033-choice-9a7cd5f9","label":"B","text":"Invalid in form, but sound."},{"id":"LOGIC-033-choice-e1024850","label":"C","text":"Valid in form, but not sound because the first premise is false."},{"id":"LOGIC-033-choice-9faca0fb","label":"D","text":"Valid and sound because 3 is odd."}],"correctChoiceId":"LOGIC-033-choice-e1024850","hint":"Separate the deduction pattern from the actual truth of the premises.","explanation":"The form is valid modus ponens. But “all odd integers are divisible by 4” is false, so the argument is not sound."},{"id":"LOGIC-034","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3034,"difficulty":"Medium","curriculumStandards":["3.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Premise 1: Every Guard card is blue. Conclusion: Card c7 is blue. Which additional premise makes this a valid modus ponens argument?","choices":[{"id":"LOGIC-034-choice-604e6bce","label":"A","text":"Card c7 is a Guard card."},{"id":"LOGIC-034-choice-f8bf1833","label":"B","text":"Every blue card is a Guard card."},{"id":"LOGIC-034-choice-55750baa","label":"C","text":"Card c7 is not a Guard card."},{"id":"LOGIC-034-choice-ec3220b8","label":"D","text":"Some blue cards are Guard cards."}],"correctChoiceId":"LOGIC-034-choice-604e6bce","hint":"The extra premise should establish the rule’s condition for c7.","explanation":"Guard→blue and Guard(c7) imply blue(c7). The other statements do not establish that c7 satisfies the condition."},{"id":"LOGIC-035","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3035,"difficulty":"Medium","curriculumStandards":["3.2.1","3.2.4"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Alyssa observes the sequence 2,4,6,8 and predicts that the next term is 10 by continuing the observed pattern. What type of reasoning is she using?","choices":[{"id":"LOGIC-035-choice-34e3235c","label":"A","text":"A logically valid proof that no other continuation is possible."},{"id":"LOGIC-035-choice-2594037d","label":"B","text":"Deductive reasoning: four observed terms prove every later term."},{"id":"LOGIC-035-choice-8129aa43","label":"C","text":"No reasoning, because number patterns cannot support predictions."},{"id":"LOGIC-035-choice-ce4af1bd","label":"D","text":"Inductive reasoning: a plausible pattern is extended, without a deductive guarantee."}],"correctChoiceId":"LOGIC-035-choice-ce4af1bd","hint":"Distinguish a likely continuation from a rule given for every term.","explanation":"Observations suggest adding 2, but no complete generating rule was given. This is an inductive prediction, not a proof of the next value."},{"id":"LOGIC-036","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3036,"difficulty":"Medium","curriculumStandards":["3.2.4"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"The first three rooms Alyssa visits each contain a chest. She concludes, “Every room in this dungeon contains a chest.” What is the best assessment?","choices":[{"id":"LOGIC-036-choice-fe0f8604","label":"A","text":"The conclusion is proved because three cases are enough for “every”."},{"id":"LOGIC-036-choice-98724f1b","label":"B","text":"This is deductive modus tollens."},{"id":"LOGIC-036-choice-e63b674f","label":"C","text":"The observations support a generalisation, but do not prove it for every room."},{"id":"LOGIC-036-choice-de797f4a","label":"D","text":"The conclusion must be false because only three rooms were visited."}],"correctChoiceId":"LOGIC-036-choice-e63b674f","hint":"Unvisited rooms have not been checked.","explanation":"A small set of positive examples may suggest a pattern. It neither proves the universal claim nor proves that the claim is false."},{"id":"LOGIC-037","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3037,"difficulty":"Hard","curriculumStandards":["3.2.4","3.2.5"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"To support a generalisation about all rooms across both dungeon stages, which evidence is strongest among these choices? Sampling is honest and room results are recorded correctly.","choices":[{"id":"LOGIC-037-choice-3c391d22","label":"A","text":"One room visited many times and counted as many different rooms."},{"id":"LOGIC-037-choice-a284f7a0","label":"B","text":"Only rooms already known to support the claim."},{"id":"LOGIC-037-choice-930f4cad","label":"C","text":"A large random sample spread across both stages and room types."},{"id":"LOGIC-037-choice-89e05a96","label":"D","text":"Three neighbouring rooms from Stage 1 only."}],"correctChoiceId":"LOGIC-037-choice-930f4cad","hint":"Consider sample size, variety and selection bias.","explanation":"A large random sample across the target population gives broader, less biased support. It still does not turn an inductive claim into a deductive certainty."},{"id":"LOGIC-038","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3038,"difficulty":"Medium","curriculumStandards":["3.2.1"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Argument A applies the given rule “all multiples of 4 are even” to 12. Argument B observes several even results and predicts that an untested case will also be even. Classify A and B.","choices":[{"id":"LOGIC-038-choice-b6ba12a8","label":"A","text":"A is inductive; B is deductive."},{"id":"LOGIC-038-choice-67f1a43c","label":"B","text":"Both are deductive."},{"id":"LOGIC-038-choice-35550d43","label":"C","text":"Both are inductive."},{"id":"LOGIC-038-choice-b0ae7da1","label":"D","text":"A is deductive; B is inductive."}],"correctChoiceId":"LOGIC-038-choice-b0ae7da1","hint":"A uses a general rule; B extends observations to an untested case.","explanation":"A deduces a specific consequence of a rule. B makes a generalising prediction from examples."},{"id":"LOGIC-039","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3039,"difficulty":"Hard","curriculumStandards":["3.2.3"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Given: “If a card is Fire, then it is Attack” and “Card c7 is Attack.” Which added premise is sufficient to justify “c7 is Fire” by modus ponens?","choices":[{"id":"LOGIC-039-choice-3262168a","label":"A","text":"Some Attack cards are Fire."},{"id":"LOGIC-039-choice-4ce0931d","label":"B","text":"c7 is not a Guard card."},{"id":"LOGIC-039-choice-18acf31f","label":"C","text":"Every Attack card is Fire."},{"id":"LOGIC-039-choice-93e31adf","label":"D","text":"Every Fire card is Attack."}],"correctChoiceId":"LOGIC-039-choice-18acf31f","hint":"The needed rule must go from Attack to Fire.","explanation":"Attack(c7) plus Attack→Fire establishes Fire(c7). Repeating Fire→Attack does not supply the reverse direction."},{"id":"LOGIC-040","topicId":"T3","topicCode":"LOGIC","chapter":3,"topic":"Logical Reasoning","seed":3040,"difficulty":"Hard","curriculumStandards":["3.2.2","3.2.6"],"contextKind":"FIXED_TEACHING_SCENARIO","prompt":"Assume all premises are true: (1) If a key is used, a lamp glows. (2) If the lamp glows, a trap activates. (3) The trap does not activate. Which conclusion must follow?","choices":[{"id":"LOGIC-040-choice-fcc9ae3c","label":"A","text":"Every unused key prevents every trap."},{"id":"LOGIC-040-choice-adb58687","label":"B","text":"The key was not used."},{"id":"LOGIC-040-choice-4b4c3e2f","label":"C","text":"The lamp glows."},{"id":"LOGIC-040-choice-aeea4137","label":"D","text":"The key was used."}],"correctChoiceId":"LOGIC-040-choice-adb58687","hint":"Work backwards through the two implications.","explanation":"No trap implies no glowing lamp by modus tollens. No glowing lamp then implies the key was not used. The claims concern this key, lamp and trap only."}]};if(typeof module!=='undefined')module.exports=bank;else root.DCQuestionBank=bank;})(typeof globalThis!=='undefined'?globalThis:this);
